        .args(["grep", "-nA1", "MATCH", path.to_str().unwrap()])
        .output()
        .expect("rtk grep");
    let stdout = String::from_utf8_lossy(&out.stdout);

    let has_context_dash = stdout.lines().any(|l| l.contains("-after1"));
