code:
use serde::{Serializer, Deserializer, ser::SerializeStruct, de::{Visitor, MapAccess}};
use std::fmt;

pub fn serialize<S>(num: &CustomNumber, serializer: S) -> Result<S::Ok, S::Error>
where
    S: Serializer,
{
    let mut state = serializer.serialize_struct("CustomNumber", 2)?;
    state.serialize_field("value", &num.value.to_string())?;
    state.serialize_field("metadata", &num.metadata)?;
    state.end()
}

pub fn deserialize<'de, D>(deserializer: D) -> Result<CustomNumber, D::Error>
where
    D: Deserializer<'de>,
{
    struct CustomNumberVisitor;

    impl<'de> Visitor<'de> for CustomNumberVisitor {
        type Value = CustomNumber;

        fn expecting(&self, formatter: &mut fmt::Formatter) -> fmt::Result {
            formatter.write_str("a struct with 'value' and 'metadata' fields")
        }

        fn visit_map<A>(self, mut map: A) -> Result<Self::Value, A::Error>
        where
            A: MapAccess<'de>,
        {
            let mut value: Option<u128> = None;
            let mut metadata: Option<String> = None;

            while let Some(key) = map.next_key()? {
                match key {
                    "value" => {
                        if value.is_some() {
                            return Err(serde::de::Error::duplicate_field("value"));
                        }
                        value = Some(map.next_value()?);
                    }
                    "metadata" => {
                        if metadata.is_some() {
                            return Err(serde::de::Error::duplicate_field("metadata"));
                        }
                        metadata = Some(map.next_value()?);
                    }
                    _ => {
                        return Err(serde::de::Error::unknown_field(key, &["value", "metadata"]));
                    }
                }
            }

            let value = value.ok_or_else(|| serde::de::Error::missing_field("value"))?;
            let metadata = metadata.ok_or_else(|| serde::de::Error::missing_field("metadata"))?;

            Ok(CustomNumber { value, metadata })
        }
    }

    deserializer.deserialize_struct("CustomNumber", &["value", "metadata"], CustomNumberVisitor)
}

