code:
use std::collections::HashMap;

struct LRUCache<K, V> {
    capacity: usize,
    cache: HashMap<K, V>,
    lru_order: Vec<K>,
}

impl<K: Eq + std::hash::Hash, V> LRUCache<K, V> {
    fn new(capacity: usize) -> LRUCache<K, V> {
        LRUCache {
            capacity,
            cache: HashMap::new(),
            lru_order: Vec::new(),
        }
    }

    fn get(&mut self, key: &K) -> Option<&V> {
        if let Some(&value) = self.cache.get(key) {
            self.update_lru_order(key);
            Some(&value)
        } else {
            None
        }
    }

    fn put(&mut self, key: K, value: V) {
        if self.cache.len() == self.capacity && !self.cache.contains_key(&key) {
            self.evict_lru();
        }
        self.cache.insert(key, value);
        self.update_lru_order(&key);
    }

    fn update_lru_order(&mut self, key: &K) {
        if let Some(index) = self.lru_order.iter().position(|k| k == key) {
            self.lru_order.remove(index);
        }
        self.lru_order.push(key.clone());
    }

    fn evict_lru(&mut self) {
        if let Some(oldest_key) = self.lru_order.first().cloned() {
            self.cache.remove(&oldest_key);
            self.lru_order.remove(0);
        }
    }
}

fn main() {
    let mut cache = LRUCache::new(2);
    cache.put("1", "one");
    cache.put("2", "two");
    assert_eq!(cache.get(&"1"), Some(&"one"));
    cache.put("3", "three");
    assert_eq!(cache.get(&"2"), None);
}

// Define a data structure to represent a message
struct Message {
    sender_id: u32,
    recipient_id: u32,
    label: String,
    timestamp: f64,
}

// Implement a message passing system
struct MessageSystem {
    messages: Vec<Message>,
}

impl MessageSystem {
    // Method to add a new message to the system
    fn add_message(&mut self, sender_id: u32, recipient_id: u32, label: String, timestamp: f64) {
        let message = Message {
            sender_id,
            recipient_id,
            label,
            timestamp,
        };
        self.messages.push(message);
    }

    // Method to retrieve all messages sent from a specific sender, sorted by timestamp
    fn get_messages_sent_by_sender(&self, sender_id: u32) -> Vec<&Message> {
        let mut sent_messages: Vec<&Message> = self.messages.iter()
            .filter(|message| message.sender_id == sender_id)
            .collect();
        sent_messages.sort_by(|a, b| a.timestamp.partial_cmp(&b.timestamp).unwrap());
        sent_messages
    }

    // Method to retrieve all messages received by a specific recipient, sorted by timestamp
    fn get_messages_received_by_recipient(&self, recipient_id: u32) -> Vec<&Message> {
        let mut received_messages: Vec<&Message> = self.messages.iter()
            .filter(|message| message.recipient_id == recipient_id)
            .collect();
        received_messages.sort_by(|a, b| a.timestamp.partial_cmp(&b.timestamp).unwrap());
        received_messages
    }
}

fn main() {
    // Create a message system instance
    let mut message_system = MessageSystem { messages: Vec::new() };

    // Add sample messages to the system
    message_system.add_message(1, 2, String::from("Hello"), 1.5);
    message_system.add_message(2, 1, String::from("Hi"), 2.0);
    message_system.add_message(1, 3, String::from("Meeting"), 1.0);

    // Retrieve and print messages sent by a specific sender
    let sender_id = 1;
    let sent_messages = message_system.get_messages_sent_by_sender(sender_id);
    println!("Messages sent by sender {}: {:?}", sender_id, sent_messages);

    // Retrieve and print messages received by a specific recipient
    let recipient_id = 2;
    let received_messages = message_system.get_messages_received_by_recipient(recipient_id);
    println!("Messages received by recipient {}: {:?}", recipient_id, received_messages);
}

struct Bank {
    accounts: std::collections::HashMap<u32, f64>,
    next_account_id: u32,
}

impl Bank {
    fn new() -> Bank {
        Bank {
            accounts: std::collections::HashMap::new(),
            next_account_id: 1,
        }
    }

    fn create_account(&mut self, initial_balance: f64) -> u32 {
        let account_id = self.next_account_id;
        self.accounts.insert(account_id, initial_balance);
        self.next_account_id += 1;
        account_id
    }

    fn deposit(&mut self, account_id: u32, amount: f64) -> Result<(), String> {
        if let Some(balance) = self.accounts.get_mut(&account_id) {
            *balance += amount;
            Ok(())
        } else {
            Err("Account does not exist".to_string())
        }
    }

    fn withdraw(&mut self, account_id: u32, amount: f64) -> Result<(), String> {
        if let Some(balance) = self.accounts.get_mut(&account_id) {
            if *balance >= amount {
                *balance -= amount;
                Ok(())
            } else {
                Err("Insufficient funds".to_string())
            }
        } else {
            Err("Account does not exist".to_string())
        }
    }

    fn check_balance(&self, account_id: u32) -> Result<f64, String> {
        if let Some(&balance) = self.accounts.get(&account_id) {
            Ok(balance)
        } else {
            Err("Account does not exist".to_string())
        }
    }
}

fn main() {
    let mut bank = Bank::new();
    let account1 = bank.create_account(100.0);
    let account2 = bank.create_account(50.0);

    println!("Account 1 balance: {:?}", bank.check_balance(account1)); // Output: Ok(100.0)
    println!("Account 2 balance: {:?}", bank.check_balance(account2)); // Output: Ok(50.0)

    bank.deposit(account1, 50.0).unwrap();
    bank.withdraw(account2, 20.0).unwrap();

    println!("Account 1 balance: {:?}", bank.check_balance(account1)); // Output: Ok(150.0)
    println!("Account 2 balance: {:?}", bank.check_balance(account2)); // Output: Ok(30.0)
}

