fn parse_directive_expression(expression: &str) -> Option<(&str, Option<&str>)> {
    // Trim leading and trailing whitespace
    let expression = expression.trim();

    // Check if the expression starts with '{' and ends with '}'
    if expression.starts_with('{') && expression.ends_with('}') {
        // Remove the leading '{' and trailing '}'
        let inner_expression = &expression[1..expression.len() - 1];

        // Split the inner expression by ':'
        let parts: Vec<&str> = inner_expression.split(':').collect();

        // The first part is the directive name
        let directive_name = parts[0].trim();

        // The second part, if present, is the template
        if parts.len() > 1 {
            let template = Some(parts[1].trim());
            Some((directive_name, template))
        } else {
            Some((directive_name, None))
        }
    } else {
        None
    }
}

