    let interactive = Interactive {
        throttle: 0,
        roll: 1,
        pitch: 2,
        yaw: 3,
    };
    let output: Vec<u8> = to_vec(&interactive).unwrap();
    let back: Interactive = from_bytes(&output).unwrap();
    assert_eq!(
