extern crate crypto;

use crypto::digest::Digest;
use crypto::md5::Md5;

fn correct_hash(input: String) -> bool {
    let mut hasher = Md5::new();
    hasher.input_str(&input);
    let result = hasher.result_str();

    let md5_bytes: Vec<u8> = result
        .chars()
        .flat_map(|c| c.to_digit(16))
        .map(|n| n as u8)
        .collect();

    five_leading_zeros(md5_bytes)
}

fn five_leading_zeros(md5: Vec<u8>) -> bool {
    md5.iter().take(2).all(|x| *x == 0) && md5[2] < 10
}

fn main() {
    let base = "bgvyzdsv";
    let num = (1..).find(|i| correct_hash(format!("{}{}", base, i)));
    println!("{}", num.unwrap());
}

