use crypto::sha2::Sha256;
use rustc_hex::ToHex;

#[derive(Clone)]
struct H256([u8; 32]);

impl H256 {
    fn zero() -> Self {
        H256([0; 32])
    }
}

struct Node {
    value: Option<H256>,
    children: Vec<Node>,
}

impl Node {
    fn get_child(&self, idx: usize) -> Option<&Node> {
        self.children.get(idx)
    }

    fn value_hash(&self, remaining: &[u8]) -> Option<H256> {
        match self.value {
            Some(val) => {
                let mut hasher = Sha256::new();
                hasher.input(&val.0);
                hasher.input(remaining);
                let mut output = [0; 32];
                hasher.result(&mut output);
                Some(H256(output))
            }
            None => {
                panic!("Invalid key. Branch node does not store value.");
            }
        };

        let mut child_hashes = Vec::new();
        for child in &self.children {
            if let Some(hash) = child.value_hash(remaining) {
                child_hashes.push(hash);
            } else {
                child_hashes.push(H256::zero());
            }
        }

        let mut combined_hash = H256::zero();
        for hash in child_hashes {
            let mut hasher = Sha256::new();
            hasher.input(&hash.0);
            hasher.input(&combined_hash.0);
            let mut output = [0; 32];
            hasher.result(&mut output);
            combined_hash = H256(output);
        }

        Some(combined_hash)
    }
}

