use std::collections::HashMap;

fn parse_arguments(args: &[String]) -> Result<HashMap<String, String>, String> {
    let mut config_map = HashMap::new();
    let mut iter = args.iter().peekable();

    while let Some(arg) = iter.next() {
        if arg == "--cfg" {
            if let Some(next_arg) = iter.next() {
                if next_arg.starts_with("key=") {
                    let (key, value) = next_arg.split_at(4);
                    config_map.insert(key.to_string(), value.to_string());
                } else if next_arg.starts_with("key") {
                    config_map.insert(next_arg.to_string(), "".to_string());
                } else {
                    return Err(format!("invalid `--cfg` argument: `{}` (expected `key` or `key=\"value\"`)", next_arg));
                }
            } else {
                return Err("invalid `--cfg` argument: `\"\"` (expected `key` or `key=\"value\"`)".to_string());
            }
        }
    }

    Ok(config_map)
}

