use rusttype::{Font, Scale, point, PositionedGlyph};
use std::iter::FromIterator;

fn rasterize_character(character: char, font: &Font) -> Vec<Vec<bool>> {
    let scale = Scale::uniform(20.0);
    let v_metrics = font.v_metrics(scale);
    let offset = point(10.0, v_metrics.ascent);
    let glyphs: Vec<PositionedGlyph> = font.layout(character, scale, offset).collect();

    let glyph = &glyphs[0];
    let pixel_bounds = glyph.pixel_bounding_box().unwrap();
    let width = pixel_bounds.max.x - pixel_bounds.min.x;
    let height = pixel_bounds.max.y - pixel_bounds.min.y;

    let mut image = vec![vec![false; width as usize]; height as usize];

    for y in pixel_bounds.min.y..pixel_bounds.max.y {
        for x in pixel_bounds.min.x..pixel_bounds.max.x {
            if let Some(hit) = glyph.pixel(x as f32, y as f32) {
                if hit {
                    image[(y - pixel_bounds.min.y) as usize][(x - pixel_bounds.min.x) as usize] = true;
                }
            }
        }
    }

    image
}

