enum Error {
    PtraceError,
    KillError,
    ContextError,
}

fn manage_process(handle: &Handle) -> Result<(), Error> {
    // Close the process session
    if ptrace::close_session(handle.info.pid).is_err() {
        return Err(Error::PtraceError);
    }

    // Check and send SIGKILL if O_EXCL flag is set
    if handle.info.flags & O_EXCL == O_EXCL {
        if syscall::kill(handle.info.pid, SIGKILL).is_err() {
            return Err(Error::KillError);
        }
    }

    // Update process context
    let mut contexts = context::contexts();
    if let Some(context) = contexts.get_mut(handle.info.pid) {
        let mut context = context.write();
        context.ptrace_stop = false;
    } else {
        return Err(Error::ContextError);
    }

    Ok(())
}

