use std::io::{Error, ErrorKind, Result};

struct CustomDataStructure {
    byte: [u8; 16],
}

impl CustomDataStructure {
    fn extract_bit(&self, index: usize) -> Result<u8, Error> {
        if index > 7 {
            return Err(Error::new(
                ErrorKind::InvalidData,
                "Index out of range for byte",
            ));
        }
        let bit = (self.byte[0] >> (7 - index)) & 1;
        Ok(bit)
    }

    pub fn read_bits(&mut self, number_of_bits: usize) -> Result<u128, Error> {
        if number_of_bits > 128 {
            return Err(Error::new(
                ErrorKind::InvalidData,
                "Tried to read more than 128 bits",
            ));
        }
        let mut result: u128 = 0;
        for i in 0..number_of_bits {
            let bit = self.extract_bit(i)?;
            result = (result << 1) | u128::from(bit);
        }
        Ok(result)
    }
}

