use std::fs::File;
use std::io::{Error, Read};

fn parse_elf_sections(elf_file: &str) -> Result<HashMap<String, u64>, Error> {
    let mut file = File::open(elf_file)?;
    let mut buffer = Vec::new();
    file.read_to_end(&mut buffer)?;

    let mut section_map = HashMap::new();
    let mut offset = 0;

    // Parse the ELF file to extract section names and their lengths
    while offset < buffer.len() {
        let section_name_offset = u32::from_le_bytes([
            buffer[offset],
            buffer[offset + 1],
            buffer[offset + 2],
            buffer[offset + 3],
        ]) as usize;

        let section_size = u64::from_le_bytes([
            buffer[offset + 16],
            buffer[offset + 17],
            buffer[offset + 18],
            buffer[offset + 19],
            buffer[offset + 20],
            buffer[offset + 21],
            buffer[offset + 22],
            buffer[offset + 23],
        ]);

        let section_name = &buffer[section_name_offset..].split(|&x| x == 0).next().unwrap();
        let section_name_str = String::from_utf8_lossy(section_name).to_string();

        section_map.insert(section_name_str, section_size);

        offset += 40; // Each section header is 40 bytes long
    }

    Ok(section_map)
}

