        builder.position_at_end(basic_block);

        let i32_type = context.i32_type();
        let exit_code = i32_type.const_int(0, false);
        builder.build_return(Some(&exit_code));

        let jit_function = JitFunction::new(&function, &execution_engine)?;

        let res = jit_function.call();
        println!("Exit code: {}", res);
        Ok(())
