struct Post {
    title: String,
    author: String,
    content: String,
    url: String,
}

fn generate_html_files(posts: Vec<Post>) {
    for post in posts {
        let file_name = format!("{}index.html", post.url);
        let f = File::create(&file_name).expect("Failed to create file");
        {
            let mut writer = BufWriter::new(f);
            writer.write(post.content.as_bytes()).expect("Failed to write to file");
        }
    }
}

fn main() {
    let posts = vec![
        Post {
            title: "First Post".to_string(),
            author: "John Doe".to_string(),
            content: "<h1>Hello, World!</h1>".to_string(),
            url: "first-post".to_string(),
        },
        Post {
            title: "Second Post".to_string(),
            author: "Jane Smith".to_string(),
            content: "<p>This is the second post.</p>".to_string(),
            url: "second-post".to_string(),
        },
    ];

    generate_html_files(posts);
}

