fn process_ipv4_packet(packet: &[u8], interface_name: &str) {
    if packet.len() < 20 {
        println!("[{}]: Malformed IPv4 Packet - Packet length less than 20 bytes", interface_name);
        return;
    }

    let version = (packet[0] & 0xF0) >> 4;
    if version != 4 {
        println!("[{}]: Malformed IPv4 Packet - Invalid version", interface_name);
        return;
    }

    let header_length = (packet[0] & 0x0F) * 4;
    if header_length < 20 {
        println!("[{}]: Malformed IPv4 Packet - Invalid header length", interface_name);
        return;
    }

    let total_length = u16::from_be_bytes([packet[2], packet[3]]);
    if total_length as usize != packet.len() {
        println!("[{}]: Malformed IPv4 Packet - Invalid total length", interface_name);
        return;
    }

    let header_checksum = u16::from_be_bytes([packet[10], packet[11]]);
    let calculated_checksum = calculate_checksum(&packet[..header_length as usize]);
    if header_checksum != calculated_checksum {
        println!("[{}]: Malformed IPv4 Packet - Invalid header checksum", interface_name);
        return;
    }

    let source_ip = format!("{}.{}.{}.{}", packet[12], packet[13], packet[14], packet[15]);
    let destination_ip = format!("{}.{}.{}.{}", packet[16], packet[17], packet[18], packet[19]);

    println!("[{}]: Valid IPv4 Packet - Source IP: {}, Destination IP: {}", interface_name, source_ip, destination_ip);
}

fn calculate_checksum(data: &[u8]) -> u16 {
    let mut sum: u32 = 0;
    for i in (0..data.len()).step_by(2) {
        if i + 1 < data.len() {
            sum += u16::from_be_bytes([data[i], data[i + 1]]) as u32;
        } else {
            sum += (data[i] as u32) << 8;
        }
    }
    while (sum >> 16) > 0 {
        sum = (sum & 0xFFFF) + (sum >> 16);
    }
    !sum as u16
}

