    fn from_guifont(font_string: &str) -> Result<Font, String> {
        let parts: Vec<&str> = font_string.split(':').collect();
        if parts.len() != 2 {
            return Err("Invalid font string format".to_string());
        }

        let font_info: Vec<&str> = parts[1].split(':').collect();
        if font_info.len() != 2 {
