use bitvec::prelude::*;

struct BitVec<Endian, T> {
    endianness: Endian,
    value: T,
}

impl<Endian, T> BitVec<Endian, T>
where
    Endian: BitOrder,
    T: BitStore,
{
    fn encode(&self) -> BitVec<Msb0, T> {
        let mut bits = BitVec::new();
        bits.extend_from_slice(self.value.as_bitslice::<Endian>());
        bits
    }

    fn decode(bits: &mut BitSlice<Msb0, T>) -> Option<T> {
        if bits.len() == T::Mem::BITS {
            let mut value = T::Mem::ZERO;
            for (i, bit) in bits.iter().enumerate() {
                if *bit {
                    value.set(i, true);
                }
            }
            Some(T::from_le_bytes(value.to_le_bytes()))
        } else {
            None
        }
    }
}

fn main() {
    // Example usage
    let value: u8 = 42;
    let bitvec = BitVec {
        endianness: Msb0,
        value,
    };
    let encoded = bitvec.encode();
    let decoded = BitVec::<Msb0, u8>::decode(&mut &encoded[..]).unwrap();
    assert_eq!(value, decoded);
}

