fn longest_palindrome(s: &str) -> String {
    if s.is_empty() {
        return String::new();
    }

    let mut start = 0;
    let mut end = 0;

    for i in 0..s.len() {
        let (left1, right1) = find_palindrome(&s, i, i);
        let (left2, right2) = find_palindrome(&s, i, i + 1);

        let len1 = right1 - left1;
        let len2 = right2 - left2;

        let max_len = std::cmp::max(len1, len2);

        if max_len > end - start {
            start = i - (max_len - 1) / 2;
            end = i + max_len / 2;
        }
    }

    s[start..=end].to_string()
}

