use crate::ray::Ray;
use crate::hittable::HitRecord;
use crate::vec3::{Color, Point3, Vec3};
use crate::scatter::{ScatterRecord, ScatterType};
use rand::Rng;

pub trait Material {
    fn scatter(&self, r_in: &Ray, rec: &HitRecord) -> Option<ScatterRecord>;
}

pub struct Lambertian {
    albedo: Color,
}

impl Material for Lambertian {
    fn scatter(&self, _r_in: &Ray, rec: &HitRecord) -> Option<ScatterRecord> {
        let mut rng = rand::thread_rng();
        let scatter_direction = rec.normal + Vec3::random_unit_vector(&mut rng);

        // If the scatter direction is near zero, choose a different random direction
        if scatter_direction.near_zero() {
            scatter_direction = rec.normal;
        }

        let scattered = Ray::new(rec.p, scatter_direction);
        let attenuation = self.albedo;

        Some(ScatterRecord {
            scatter_type: ScatterType::Diffuse,
            specular_ray: None,
            attenuation,
            scattered,
        })
    }
}

