use std::collections::BTreeMap;

fn generate_summary_report(test_results: &[(String, bool)]) -> (usize, usize, usize, Vec<String>) {
    let total_tests = test_results.len();
    let passed_tests = test_results.iter().filter(|(_, outcome)| *outcome).count();
    let failed_tests = total_tests - passed_tests;
    let failed_test_names: Vec<String> = test_results
        .iter()
        .filter(|(_, outcome)| !*outcome)
        .map(|(name, _)| name.clone())
        .collect();

    (total_tests, passed_tests, failed_tests, failed_test_names)
