use reqwest;
use serde_json;
use bytes;

#[derive(Debug)]
enum FetchError {
    ExecuteRequestError(reqwest::Error),
    ResponseBytesError(reqwest::Error),
    DeserializeError {
        source: serde_json::Error,
        body: bytes::Bytes,
    },
}

fn fetch_and_deserialize(url: &str) -> Result<serde_json::Value, FetchError> {
    let response = reqwest::blocking::get(url).map_err(FetchError::ExecuteRequestError)?;

