use std::io::{Error, ErrorKind};

enum Parsed {
    Pushd(String),
    Popd,
}

fn parse_command(command: &str, value: &str) -> Result<Parsed, Error> {
    match command {
        "@pushd" => {
            if value.is_empty() {
                Err(Error::new(ErrorKind::InvalidData, "@pushd requires a directory argument"))
            } else {
                Ok(Parsed::Pushd(value.to_string()))
            }
        },
        "@popd" => {
            if !value.is_empty() {
                Err(Error::new(ErrorKind::InvalidData, "@popd does not accept arguments"))
            } else {
                Ok(Parsed::Popd)
            }
        },
        _ => Err(Error::new(ErrorKind::InvalidData, "Unknown command")),
    }
}

fn main() {
    // Example usage
    match parse_command("@pushd", "/path/to/directory") {
        Ok(Parsed::Pushd(dir)) => println!("Pushd to directory: {}", dir),
        Err(e) => eprintln!("Error: {}", e),
        _ => unreachable!(),
    }

    match parse_command("@popd", "") {
        Ok(Parsed::Popd) => println!("Popd"),
        Err(e) => eprintln!("Error: {}", e),
        _ => unreachable!(),
    }
}

