fn encrypt_decrypt_works() {
    let (pk, sk) = box_::gen_keypair();
    let (pk, sk) = (pk[..].to_vec(), sk[..].to_vec());

    let doc = randombytes::randombytes(16);

    let encrypted_data = Sealbox::encrypt(&pk, &doc).unwrap();
