    use sodiumoxide::crypto::box_;

    pub fn encrypt(public_key: &[u8], document: &[u8]) -> Result<Vec<u8>, &'static str> {
        let pk = box_::PublicKey::from_slice(public_key).ok_or("Invalid public key")?;
        let sk = box_::gen_keypair().1;
        let nonce = box_::gen_nonce();
        let encrypted = box_::seal(document, &nonce, &pk, &sk);
