pub fn search_in_rotated_array(arr: &[isize], targ: isize) -> Option<usize> {
    if arr.is_empty() {
        return None;
    }

    let (mut left, mut right) = (0, arr.len() - 1);

    while left <= right {
        let mid = left + (right - left) / 2;

        if arr[mid] == targ {
            return Some(mid);
        }

        if arr[left] == arr[mid] && arr[mid] == arr[right] {
            left += 1;
            right -= 1;
        } else if arr[left] <= arr[mid] {
            if arr[left] <= targ && targ < arr[mid] {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        } else {
            if arr[mid] < targ && targ <= arr[right] {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
    }

    None
}

use core::fmt::Write;
use core::mem::size_of;

struct CircularBuffer {
    buffer: Vec<u8>,
    size: usize,
    read_index: usize,
    write_index: usize,
}

impl CircularBuffer {
    fn new(size: usize) -> CircularBuffer {
        CircularBuffer {
            buffer: vec![0; size],
            size,
            read_index: 0,
            write_index: 0,
        }
    }

    fn write(&mut self, value: u8) -> Result<(), &str> {
        if (self.write_index + 1) % self.size == self.read_index {
            return Err("Buffer is full");
        }
        self.buffer[self.write_index] = value;
        self.write_index = (self.write_index + 1) % self.size;
        Ok(())
    }

    fn read(&mut self) -> Option<u8> {
        if self.read_index == self.write_index {
            return None;
        }
        let value = self.buffer[self.read_index];
        self.read_index = (self.read_index + 1) % self.size;
        Some(value)
    }

    fn clear(&mut self) {
        self.read_index = 0;
        self.write_index = 0;
    }
}

fn main() {
    let mut buffer = CircularBuffer::new(5);
    buffer.write(1).unwrap();
    buffer.write(2).unwrap();
    buffer.write(3).unwrap();
    assert_eq!(buffer.read(), Some(1));
    buffer.write(4).unwrap();
    buffer.write(5).unwrap();
    buffer.write(6).unwrap(); // This will overwrite the oldest element (2)
    assert_eq!(buffer.read(), Some(3));
    buffer.clear();
    assert_eq!(buffer.read(), None);
}

