fn decode_password(url: &str) -> String {
    let parts: Vec<&str> = url.split(':').collect();
    if parts.len() < 3 {
        panic!("Invalid URL format");
    }
    let encoded_password = parts[2].split('@').next().unwrap();
    let decoded_password = hex_decode(encoded_password);
    decoded_password
}

fn hex_decode(encoded: &str) -> String {
    let mut decoded = String::new();
    let mut bytes = Vec::new();
    let mut i = 0;
    while i < encoded.len() {
        if &encoded[i..i + 1] == "%" {
            let byte = u8::from_str_radix(&encoded[i + 1..i + 3], 16).unwrap();
            bytes.push(byte);
            i += 3;
        } else {
            bytes.push(encoded.as_bytes()[i]);
            i += 1;
        }
    }
    decoded.push_str(&String::from_utf8(bytes).unwrap());
    decoded
}

