pub mod demuxer {
    use super::define::DataType;
    use super::demuxer_tag::Taggable;
    use super::errors::DemuxerError;

    pub fn demux(data: Vec<DataType>) -> Result<Vec<Vec<DataType>>, DemuxerError> {
        let mut demuxed_data: Vec<Vec<DataType>> = vec![Vec::new(); 3]; // Assuming 3 types for simplicity

        for item in data {
            match item {
                DataType::TypeA => demuxed_data[0].push(item),
                DataType::TypeB => demuxed_data[1].push(item),
                DataType::TypeC => demuxed_data[2].push(item),
            }
        }

        if demuxed_data.iter().any(|v| v.is_empty()) {
            Err(DemuxerError::InvalidData)
        } else {
            Ok(demuxed_data)
        }
    }

    pub fn tag_data(data: &Vec<DataType>) -> Result<Vec<String>, DemuxerError> {
        let mut tagged_data: Vec<String> = Vec::new();

        for item in data {
            tagged_data.push(item.tag());
        }

        if tagged_data.len() != data.len() {
            Err(DemuxerError::TaggingError)
        } else {
            Ok(tagged_data)
        }
    }
}

