code:
use std::collections::VecDeque;
use std::io;
use tokio::fs::File;
use tokio::io::AsyncReadExt;

async fn listen_for_msg(
    port: &mut File,
    leftover_buffer: &mut VecDeque<u8>,
) -> io::Result<(Vec<u8>, usize)> {
    let mut input_buffer = [0u8; 1024];
    let mut output_buffer = vec![0u8; 1024];
    let mut decoder = cobs::CobsDecoder::new(&mut output_buffer);

    // Read data from the port into the input_buffer
    let bytes_read = port.read(&mut input_buffer).await?;

    // Append any leftover bytes from the previous read to the input_buffer
    input_buffer[..leftover_buffer.len()].copy_from_slice(&leftover_buffer);
    let input_len = bytes_read + leftover_buffer.len();
    let input_buffer = &input_buffer[..input_len];

    // Decode the COBS-encoded message from the input_buffer
    let decoded_len = decoder.decode(input_buffer)?;

    // Extract the decoded message from the output_buffer
    let decoded_message = output_buffer[..decoded_len].to_vec();

    // Update the leftover_buffer with any remaining bytes
    let remaining_bytes = &input_buffer[decoded_len..];
    leftover_buffer.clear();
    leftover_buffer.extend_from_slice(remaining_bytes);

    Ok((decoded_message, bytes_read))
}

