fn parse_macro_pattern(macro_definition: &str, pattern: &str) -> Vec<String> {
    // Your implementation here
}
```

For example, given the following macro definition:
```rust
macro_rules! my_macro {
    ($($x:expr),*) => {
        // Some code here
        otry!($($x),*);
        // More code here
    }
}
```
and the pattern `otry!`, the function should return `vec!["otry!($($x),*)"]`.

Assume that the input macro definition is well-formed and follows the syntax rules of Rust macros.

code:
fn parse_macro_pattern(macro_definition: &str, pattern: &str) -> Vec<String> {
    let mut occurrences = Vec::new();
    let mut in_macro = false;
    let mut current_macro = String::new();

    for line in macro_definition.lines() {
        if line.contains("macro_rules!") {
            in_macro = true;
            continue;
        }
        if in_macro {
            if line.contains(pattern) {
                current_macro.push_str(line.trim());
                while !current_macro.ends_with(';') {
                    current_macro.push_str(macro_definition.lines().next().unwrap().trim());
                }
                occurrences.push(current_macro.clone());
                current_macro.clear();
            }
        }
    }

    occurrences
}

