use std::time::{Instant, Duration};

struct Timer {
    metric: String,
    start_time: Option<Instant>,
}

impl Timer {
    fn new(metric: String) -> Timer {
        Timer {
            metric: metric,
            start_time: None,
        }
    }

    fn start(&mut self) {
        self.start_time = Some(Instant::now());
    }

    fn stop(&mut self) -> Result<u64, &str> {
        match self.start_time {
            Some(start) => {
                let elapsed = start.elapsed().as_millis();
                self.start_time = None;
                Ok(elapsed as u64)
            }
            None => Err("Timer has not been started"),
        }
    }
}

