use trust_dns::client::{Client, SyncClient};
use trust_dns::op::Message;
use trust_dns::rr::{DNSClass, Name, RecordType};
use trust_dns::udp::UdpClientConnection;

fn trace(domain: &str) -> Result<String, String> {
    let root_servers = vec!["198.41.0.4", "192.228.79.201", "192.33.4.12", "199.7.91.13", "192.203.230.10", "192.5.5.241", "192.112.36.4", "198.97.190.53", "192.36.148.17", "192.58.128.30", "193.0.14.129", "199.7.83.42", "202.12.27.33"];

    let mut current_domain = domain.to_string();
    let mut client = SyncClient::new(Client::new(UdpClientConnection::new("8.8.8.8".parse().unwrap(), None).unwrap()));

    loop {
        let query = client.query(&Name::from_str(&current_domain).unwrap(), DNSClass::IN, RecordType::NS);
        let response = match query {
            Ok(response) => response,
            Err(_) => return Err("Failed to query name server".to_string()),
        };

        if let Some(answer) = response.answers().iter().next() {
            if let Some(ns) = answer.rdata().as_ns() {
                current_domain = ns.to_string();
            } else {
                return Err("No NS record found".to_string());
            }
        } else {
            return Err("No answer found".to_string());
        }

        if root_servers.contains(&current_domain.as_str()) {
            return Ok(current_domain);
        }
    }
}

