struct Bank {
    accounts: Vec<Account>,
}

impl Bank {
    fn new() -> Bank {
        Bank { accounts: Vec::new() }
    }

    fn create_account(&mut self, holder_name: String) -> Account {
        let account_number = self.accounts.len() as u32 + 1;
        let account = Account::new(holder_name, account_number);
        self.accounts.push(account.clone());
        account
    }

    fn get_account_by_number(&self, account_number: u32) -> Option<&Account> {
        self.accounts.iter().find(|&acc| acc.account_number == account_number)
    }

    fn deposit(&mut self, account_number: u32, amount: f64) -> Result<(), &'static str> {
        if let Some(account) = self.get_account_by_number(account_number) {
            account.deposit(amount);
            Ok(())
        } else {
            Err("Account not found")
        }
    }

    fn withdraw(&mut self, account_number: u32, amount: f64) -> Result<(), &'static str> {
        if let Some(account) = self.get_account_by_number(account_number) {
            account.withdraw(amount)
        } else {
            Err("Account not found")
        }
    }

    fn check_balance(&self, account_number: u32) -> Result<f64, &'static str> {
        if let Some(account) = self.get_account_by_number(account_number) {
            Ok(account.check_balance())
        } else {
            Err("Account not found")
        }
    }

    fn transfer_funds(&mut self, from_account: u32, to_account: u32, amount: f64) -> Result<(), &'static str> {
        if let Some(from) = self.get_account_by_number(from_account) {
            if let Some(to) = self.get_account_by_number(to_account) {
                if from.balance >= amount {
                    from.withdraw(amount)?;
                    to.deposit(amount);
                    Ok(())
                } else {
                    Err("Insufficient funds for transfer")
                }
            } else {
                Err("Invalid 'to' account number")
            }
        } else {
            Err("Invalid 'from' account number")
        }
    }
}

fn main() {
    let mut bank = Bank::new();
    let account1 = bank.create_account("Alice".to_string());
    let account2 = bank.create_account("Bob".to_string());

    bank.deposit(account1.account_number, 100.0).unwrap();
    bank.deposit(account2.account_number, 50.0).unwrap();

    bank.transfer_funds(account1.account_number, account2.account_number, 30.0).unwrap();

    assert_eq!(bank.check_balance(account1.account_number).unwrap(), 70.0);
    assert_eq!(bank.check_balance(account2.account_number).unwrap(), 80.0);
}

