#[derive(Debug)]
enum OperandSize {
    Byte,
    Word,
    Dword,
    Qword,
}

fn execute_arithmetic_operation(stack: &mut Vec<i64>, operation_code: u8, operand_size: Option<OperandSize>) {
    if stack.len() < 2 {
        return; // Not enough elements on the stack to perform the operation
    }

    let operand_size = operand_size.unwrap_or(OperandSize::Dword); // Default to Dword if operand size is not specified

    let operand1 = stack.pop().unwrap();
    let operand2 = stack.pop().unwrap();

    let result = match operand_size {
        OperandSize::Byte => match operation_code {
            0 => (operand1 as i8 + operand2 as i8) as i64, // Addition
            1 => (operand2 as i8 - operand1 as i8) as i64, // Subtraction
            2 => (operand1 as i8 * operand2 as i8) as i64, // Multiplication
            3 => (operand2 as i8 / operand1 as i8) as i64, // Division
            _ => 0, // Invalid operation code
        },
        OperandSize::Word => match operation_code {
            0 => (operand1 as i16 + operand2 as i16) as i64, // Addition
            1 => (operand2 as i16 - operand1 as i16) as i64, // Subtraction
            2 => (operand1 as i16 * operand2 as i16) as i64, // Multiplication
            3 => (operand2 as i16 / operand1 as i16) as i64, // Division
            _ => 0, // Invalid operation code
        },
        OperandSize::Dword => match operation_code {
            0 => operand1 + operand2, // Addition
            1 => operand2 - operand1, // Subtraction
            2 => operand1 * operand2, // Multiplication
            3 => operand2 / operand1, // Division
            _ => 0, // Invalid operation code
        },
        OperandSize::Qword => match operation_code {
            0 => operand1 + operand2, // Addition
            1 => operand2 - operand1, // Subtraction
            2 => operand1 * operand2, // Multiplication
            3 => operand2 / operand1, // Division
            _ => 0, // Invalid operation code
        },
    };

    stack.push(result);
}

fn main() {
    let mut stack = vec![10, 5]; // Example stack with two elements
    execute_arithmetic_operation(&mut stack, 0, Some(OperandSize::Dword)); // Perform addition with Dword operand size
    println!("{:?}", stack); // Output: [15]
}

