use std::fs;
use std::io;
use std::io::BufRead;

fn calculate_surface_area(obj_file_path: &str) -> Result<f64, String> {
    let file_content = match fs::read_to_string(obj_file_path) {
        Ok(content) => content,
        Err(_) => return Err("Error reading file".to_string()),
    };

    let mut vertices: Vec<(f64, f64, f64)> = Vec::new();
    let mut faces: Vec<(usize, usize, usize)> = Vec::new();

    for line in file_content.lines() {
        let parts: Vec<&str> = line.split_whitespace().collect();
        if parts.is_empty() {
            continue;
        }
        match parts[0] {
            "v" => {
                if let [x, y, z] = parts[1..].iter().filter_map(|s| s.parse().ok()).collect::<Vec<f64>>().as_slice() {
                    vertices.push((*x, *y, *z));
                } else {
                    return Err("Invalid vertex format".to_string());
                }
            }
            "f" => {
                if let [v1, v2, v3] = parts[1..].iter().filter_map(|s| s.parse::<usize>().ok()).collect::<Vec<usize>>().as_slice() {
                    faces.push((*v1 - 1, *v2 - 1, *v3 - 1)); // OBJ indices are 1-based
                } else {
                    return Err("Invalid face format".to_string());
                }
            }
            _ => {}
        }
    }

    let mut total_area = 0.0;
    for (v1, v2, v3) in faces {
        let p1 = vertices[v1];
        let p2 = vertices[v2];
        let p3 = vertices[v3];
        let edge1 = (p2.0 - p1.0, p2.1 - p1.1, p2.2 - p1.2);
        let edge2 = (p3.0 - p1.0, p3.1 - p1.1, p3.2 - p1.2);
        let cross_product = (
            edge1.1 * edge2.2 - edge1.2 * edge2.1,
            edge1.2 * edge2.0 - edge1.0 * edge2.2,
            edge1.0 * edge2.1 - edge1.1 * edge2.0,
        );
        let area = 0.5 * (cross_product.0.powi(2) + cross_product.1.powi(2) + cross_product.2.powi(2)).sqrt();
        total_area += area;
    }

    Ok(total_area)
}

