    pub fn new() -> Self {
        Heap {
            objects: HashMap::new(),
            next_id: 1,
        }
    }

    pub fn allocate_object(&mut self, obj: JvmObject) -> u64 {
        let obj_id = self.next_id;
        self.objects.insert(obj_id, obj);
        self.next_id += 1;
        obj_id
    }

    pub fn deallocate_object(&mut self, obj_id: u64) {
        self.objects.remove(&obj_id);
    }
}

