use std::time::Duration;

struct Packet {
    sent: Duration,
    received: Option<Duration>,
}

struct PacketManager {
    recv_packets: Vec<Packet>,
}

impl PacketManager {
    /// Calculate the average time that packets are taking to return over a period of time.
    pub fn mean_recv_time(&self, time_avg: Duration) -> Option<Duration> {
        if self.recv_packets.is_empty() {
            return None;
        }
        let filtered_packets: Vec<&Packet> = self.recv_packets
            .iter()
            .filter(|x| x.received.is_some() && (x.sent + x.received.unwrap()).elapsed() < time_avg)
            .collect();

        if filtered_packets.is_empty() {
            return None;
        }

        let total_time: Duration = filtered_packets.iter()
            .map(|packet| packet.received.unwrap() - packet.sent)
            .sum();

        Some(total_time / filtered_packets.len() as u32)
    }
}

