use std::f64;

#[derive(Debug, PartialEq)]
struct Point {
    x: f64,
    y: f64,
}

impl Point {
    fn point_eq_point(lhs: &Point, rhs: &Point) -> bool {
        lhs.x == rhs.x && lhs.y == rhs.y
    }

    fn point_normalize(point: &mut Point) {
        let length = (point.x.powi(2) + point.y.powi(2)).sqrt();
        point.x /= length;
        point.y /= length;
    }

    fn point_eq_norm_point(lhs: &Point, rhs: &Point) -> bool {
        let mut rhs_norm = rhs.clone();
        Self::point_normalize(&mut rhs_norm);
        Self::point_eq_point(lhs, &rhs_norm)
    }

    fn point_eq_xonly(lhs: &Point, rhs: &XOnly) -> bool {
        lhs.x == rhs.x && lhs.y == 0.0
    }

    fn point_add_point(lhs: &Point, rhs: &Point) -> Point {
        Point {
            x: lhs.x + rhs.x,
            y: lhs.y + rhs.y,
        }
    }

    fn point_add_norm_point(lhs: &Point, rhs: &Point) -> Point {
        let mut rhs_norm = rhs.clone();
        Self::point_normalize(&mut rhs_norm);
        Self::point_add_point(lhs, &rhs_norm)
    }

    fn point_sub_point(lhs: &Point, rhs: &Point) -> Point {
        let mut rhs_neg = rhs.clone();
        Self::point_neg(&mut rhs_neg);
        Self::point_add_point(lhs, &rhs_neg)
    }

    fn point_neg(point: &mut Point) {
        point.x = -point.x;
        point.y = -point.y;
    }

    fn point_sub_norm_point(lhs: &Point, rhs: &Point) -> Point {
        let mut rhs_norm = rhs.clone();
        Self::point_normalize(&mut rhs_norm);
        Self::point_sub_point(lhs, &rhs_norm)
    }

    fn point_conditional_negate(point: &mut Point, cond: bool) {
        if cond {
            Self::point_neg(point);
        }
    }
}

#[derive(Debug, PartialEq)]
struct XOnly {
    x: f64,
}

fn main() {
    let p1 = Point { x: 3.0, y: 4.0 };
    let p2 = Point { x: 1.0, y: 2.0 };
    let mut p3 = Point { x: 5.0, y: 6.0 };

    assert_eq!(Point::point_eq_point(&p1, &p2), false);
    Point::point_normalize(&mut p3);
    assert_eq!(p3, Point { x: 5.0 / (5.0f64.powi(2) + 6.0f64.powi(2)).sqrt(), y: 6.0 / (5.0f64.powi(2) + 6.0f64.powi(2)).sqrt() });
    assert_eq!(Point::point_eq_norm_point(&p1, &p2), false);
    let x_only = XOnly { x: 1.0 };
    assert_eq!(Point::point_eq_xonly(&p1, &x_only), false);
    assert_eq!(Point::point_add_point(&p1, &p2), Point { x: 4.0, y: 6.0 });
    assert_eq!(Point::point_add_norm_point(&p1, &p2), Point { x: 3.0 + 1.0 / (1.0f64.powi(2) + 2.0f64.powi(2)).sqrt(), y: 4.0 + 2.0 / (1.0f64.powi(2) + 2.0f64.powi(2)).sqrt() });
    assert_eq!(Point::point_sub_point(&p1, &p2), Point { x: 2.0, y: 2.0 });
    assert_eq!(Point::point_sub_norm_point(&p1, &p2), Point { x: 3.0 - 1.0 / (1.0f64.powi(2) + 2.0f64.powi(2)).sqrt(), y: 4.0 - 2.0 / (1.0f64.powi(2) + 2.0f64.powi(2)).sqrt() });
    Point::point_conditional_negate(&mut p1, true);
