code:
use std::fs::File;
use std::os::unix::io::{AsRawFd, FromRawFd};
use std::ptr;
use libc::{c_void, off_t, MAP_FAILED, MAP_SHARED, PROT_READ, PROT_WRITE, ftruncate, mmap, munmap, MAP_ANON};

struct FileBackedMemoryDropWrapper {
    file: File,
    address: *mut c_void,
    mapped_length: usize,
}

impl FileBackedMemoryDropWrapper {
    fn new(file: File, length: usize) -> Self {
        let mut file = file;
        let file_len = file.metadata().unwrap().len();
        if file_len < length as u64 {
            file.set_len(length as u64).unwrap();
        }

        let address = unsafe {
            mmap(
                ptr::null_mut(),
                length,
                PROT_READ | PROT_WRITE,
                MAP_SHARED,
                file.as_raw_fd(),
                0,
            )
        };

        if address == MAP_FAILED {
            panic!("Failed to map memory");
        }

        FileBackedMemoryDropWrapper {
            file,
            address,
            mapped_length: length,
        }
    }

    fn read_memory(&self, offset: usize, buf: &mut [u8]) {
        unsafe {
            ptr::copy_nonoverlapping(
                self.address.offset(offset as isize) as *const u8,
                buf.as_mut_ptr(),
                buf.len(),
            );
        }
    }
}

impl Drop for FileBackedMemoryDropWrapper {
    fn drop(&mut self) {
        unsafe {
            munmap(self.address, self.mapped_length);
        }
    }
}

