use std::path::Path;
use std::fs;

struct TextureDirectory {
    directory_path: String,
}

enum TextureOpt {
    List,
    Add(String),
    Remove(String),
}

impl TextureDirectory {
    fn new(texture_dir: impl AsRef<Path>) -> TextureDirectory {
        let directory_path = texture_dir.as_ref().to_string_lossy().to_string();
        TextureDirectory { directory_path }
    }

    fn len(&self) -> usize {
        let entries = fs::read_dir(&self.directory_path).unwrap();
        entries.count()
    }

    fn add_texture(&mut self, texture_name: &str) -> Result<(), Box<dyn std::error::Error>> {
        let new_texture_path = format!("{}/{}", self.directory_path, texture_name);
        fs::File::create(&new_texture_path)?;
        Ok(())
    }

    fn remove_texture(&mut self, texture_name: &str) -> Result<(), Box<dyn std::error::Error>> {
        let texture_path = format!("{}/{}", self.directory_path, texture_name);
        fs::remove_file(&texture_path)?;
        Ok(())
    }
}

fn manage_textures(
    texture_dir: impl AsRef<Path>,
    opt: TextureOpt,
) -> Result<(), Box<dyn std::error::Error>> {
    let mut texture_dir = TextureDirectory::new(texture_dir);

    match opt {
        TextureOpt::List => {
            for entry in fs::read_dir(&texture_dir.directory_path)? {
                if let Ok(entry) = entry {
                    println!("{}", entry.file_name().to_string_lossy());
                }
            }
        }
        TextureOpt::Add(texture_name) => {
            texture_dir.add_texture(&texture_name)?;
        }
        TextureOpt::Remove(texture_name) => {
            texture_dir.remove_texture(&texture_name)?;
        }
    }

    Ok(())
}

