use std::collections::HashMap;

struct Cache {
    capacity: usize,
    data: HashMap<String, (String, usize)>,
    access_time: usize,
}

impl Cache {
    fn new(capacity: usize) -> Cache {
        Cache {
            capacity,
            data: HashMap::new(),
            access_time: 0,
        }
    }

    fn get(&mut self, key: &str) -> Option<&str> {
        if let Some((value, _)) = self.data.get_mut(key) {
            *self.data.get_mut(key).unwrap().1 = self.access_time;
            self.access_time += 1;
            Some(value)
        } else {
            None
        }
    }

    fn put(&mut self, key: &str, value: &str) {
        if self.data.len() >= self.capacity {
            let (evict_key, _) = self.data
                .iter()
                .min_by_key(|(_, &(_, access_time))| access_time)
                .unwrap()
                .clone();
            self.data.remove(&evict_key);
        }
        self.data.insert(key.to_string(), (value.to_string(), self.access_time));
        self.access_time += 1;
    }
}

fn main() {
    let mut cache = Cache::new(2);
    cache.put("1", "one");
    cache.put("2", "two");
    assert_eq!(cache.get("1"), Some("one"));
    cache.put("3", "three");
    assert_eq!(cache.get("2"), None);
}

