assert_eq!(parse_mime_type("application/json"), Ok(("application".to_string(), "json".to_string())));
assert_eq!(parse_mime_type("image/png"), Ok(("image".to_string(), "png".to_string())));
assert_eq!(parse_mime_type("invalid"), Err("Invalid MIME type".to_string()));
```

code:
fn parse_mime_type(mime_type: &str) -> Result<(String, String), String> {
    let parts: Vec<&str> = mime_type.split('/').collect();
    if parts.len() != 2 {
        return Err("Invalid MIME type".to_string());
    }
    let mime_type = parts[0].trim().to_string();
    let subtype = parts[1].trim().to_string();
    Ok((mime_type, subtype))
}

