extern crate imagefmt;
extern crate docopt;
extern crate rustc_serialize;

use docopt::Docopt;
use imagefmt::{ColFmt, ColType};

static USAGE: &str = "
Usage: grayscale_converter --input <input_file> --output <output_file>
       grayscale_converter (-h | --help)

Options:
  -h, --help            Show this help message.
  --input <input_file>  Input image file path.
  --output <output_file>  Output grayscale image file path.
";

#[derive(Debug, RustcDecodable)]
struct Args {
    flag_input: String,
    flag_output: String,
}

fn main() {
    let args: Args = Docopt::new(USAGE)
        .and_then(|d| d.decode())
        .unwrap_or_else(|e| e.exit());

    let input_file = &args.flag_input;
    let output_file = &args.flag_output;

    // Read the input image file
    let img = imagefmt::read(input_file, ColFmt::Auto).expect("Failed to read input image");

    // Convert the image to grayscale
    let grayscale_img = imagefmt::convert_colors(&img, ColType::Gray).expect("Failed to convert to grayscale");

    // Save the grayscale image to the output file
    imagefmt::write(output_file, grayscale_img, ColFmt::Auto).expect("Failed to write grayscale image");
}

