        if let Some(index) = self.nodes.iter().position(|node| node.name == name) {
            let stars_to_remove = self.nodes[index].stars;
            self.nodes.remove(index);
            self.total_stars -= stars_to_remove;
        }
    }

    // Get the total number of stars associated with the graph
    fn get_total_stars(&self) -> u32 {
        self.total_stars
    }
}

