fn evaluate_expression(expression: &str) -> Option<i32> {
    let tokens: Vec<char> = expression.chars().filter(|&c| c != ' ').collect();
    let mut index = 0;

    fn parse_num(tokens: &Vec<char>, index: &mut usize) -> i32 {
        let mut num = 0;
        while *index < tokens.len() && tokens[*index].is_digit(10) {
            num = num * 10 + tokens[*index].to_digit(10).unwrap() as i32;
            *index += 1;
        }
        num
    }

    fn parse_term(tokens: &Vec<char>, index: &mut usize) -> i32 {
        let mut result = parse_num(tokens, index);
        while *index < tokens.len() {
            match tokens[*index] {
                '*' => {
                    *index += 1;
                    result *= parse_num(tokens, index);
                }
                '/' => {
                    *index += 1;
                    result /= parse_num(tokens, index);
                }
                _ => break,
            }
        }
        result
    }

    fn parse_expression(tokens: &Vec<char>, index: &mut usize) -> i32 {
        let mut result = parse_term(tokens, index);
        while *index < tokens.len() {
            match tokens[*index] {
                '+' => {
                    *index += 1;
                    result += parse_term(tokens, index);
                }
                '-' => {
                    *index += 1;
                    result -= parse_term(tokens, index);
                }
                _ => break,
            }
        }
        result
    }

    let result = parse_expression(&tokens, &mut index);
    if index == tokens.len() {
        Some(result)
    } else {
        None
    }
}

