use std::fmt::Display;

fn text_box<T: Display, S: Display>(
    mut lines: impl Iterator<Item=T>,
    header: Option<S>,
) -> impl Iterator<Item=String> {
    let mut result = Vec::new();
    let mut max_line_length = 0;

    // Calculate the maximum line length
    lines.clone().for_each(|line| {
        let line_length = format!("{}", line).len();
        if line_length > max_line_length {
            max_line_length = line_length;
        }
    });

    // Calculate the width of the text box
    let width = max_line_length.max(header.as_ref().map_or(0, |h| format!("{}", h).len()));

    // Generate the top border
    result.push(format!("+{}+", "-".repeat(width + 2)));

    // Generate the header if present
    if let Some(h) = header {
        let header_str = format!("{}", h);
        let padding = (width - header_str.len()) / 2;
        let left_padding = "-".repeat(padding);
        let right_padding = "-".repeat(width - header_str.len() - padding);
        result.push(format!("|{} {}{}{} |", left_padding, header_str, right_padding, " ".repeat(width - header_str.len())));
        result.push(format!("+{}+", "-".repeat(width + 2)));
    }

    // Generate the lines of text
    lines.for_each(|line| {
        let line_str = format!("{}", line);
        let padding = " ".repeat(width - line_str.len());
        result.push(format!("| {}{} |", line_str, padding));
    });

    // Generate the bottom border
    result.push(format!("+{}+", "-".repeat(width + 2)));

    result.into_iter()
}

