        let new_ty = (self.b * self.tx - self.a * self.ty) * inv_det;

        Some(LocalToWorld {
            a: new_a,
            b: new_b,
            c: new_c,
            d: new_d,
            tx: new_tx,
            ty: new_ty,
        })
    }
}

