fn movePlayer(grid: &mut [[i32; 5]; 5], direction: &str) -> (usize, usize) {
    let mut player_position = (0, 0);
    for (i, row) in grid.iter().enumerate() {
        for (j, &cell) in row.iter().enumerate() {
            if cell == 1 {
                player_position = (i, j);
                break;
            }
        }
    }

    let (mut x, mut y) = player_position;
    match direction {
        "up" => {
            if x > 0 {
                x -= 1;
            }
        }
        "down" => {
            if x < grid.len() - 1 {
                x += 1;
            }
        }
        "left" => {
            if y > 0 {
                y -= 1;
            }
        }
        "right" => {
            if y < grid[0].len() - 1 {
                y += 1;
            }
        }
        _ => {}
    }

    grid[player_position.0][player_position.1] = 0; // Clear the previous position
    grid[x][y] = 1; // Update the new position

    (x, y)
}

