use std::sync::atomic::{AtomicU8, Ordering};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum StoragePreference {
    Low,
    Medium,
    High,
}

pub struct AtomicStoragePreference(AtomicU8);

impl AtomicStoragePreference {
    pub fn new(preference: StoragePreference) -> Self {
        let value = match preference {
            StoragePreference::Low => 0,
            StoragePreference::Medium => 1,
            StoragePreference::High => 2,
        };
        AtomicStoragePreference(AtomicU8::new(value))
    }

    pub fn upgrade(&self, new_preference: StoragePreference) {
        let new_value = match new_preference {
            StoragePreference::Low => 0,
            StoragePreference::Medium => 1,
            StoragePreference::High => 2,
        };

        loop {
            let current = self.0.load(Ordering::SeqCst);
            if current == 2 {
                // Maximum value reached, no upgrade needed
                break;
            }
            if current == new_value {
                // Preference already set, no upgrade needed
                break;
            }
            let result = self.0.compare_exchange(current, new_value, Ordering::SeqCst, Ordering::SeqCst);
            match result {
                Ok(_) => {
                    // Upgrade successful
                    break;
                }
                Err(_) => {
                    // Another thread modified the value, retry
                    continue;
                }
            }
        }
    }
}

