impl IntBlockPool {
    /// Resets the pool to its initial state reusing the first buffer.
    pub fn reset(&mut self, zero_fill_buffers: bool, reuse_first: bool) {
        if self.buffer_upto > -1 {
            if zero_fill_buffers {
                for buffer in &mut self.buffers {
                    for val in buffer.iter_mut() {
                        *val = 0; // Zero-fill the buffer
                    }
                }
            }
            if reuse_first {
                for i in 1..self.buffers.len() {
                    self.buffers[i].clear(); // Clear all buffers except the first one
                }
                self.buffer_upto = 0; // Reset the buffer index
            } else {
                for buffer in &mut self.buffers {
                    buffer.clear(); // Clear all buffers
                }
                self.buffer_upto = -1; // Reset the buffer index
            }
            self.int_upto = INT_BLOCK_SIZE; // Reset the integer upper limit
            self.int_offset = -(INT_BLOCK_SIZE as isize); // Reset the integer offset
            self.need_flush = false; // Reset the flush flag
            self.allocator.reset(); // Reset the allocator
        }
    }
}

