                pieces_to_check.contains(&(row + 1, col + 1)) &&
                pieces_to_check.contains(&(row + 2, col + 2)) &&
                pieces_to_check.contains(&(row + 3, col + 3)) {
                return true;
            }

            // Check for a diagonal win (bottom-left to top-right)
            if row >= 3 && col <= 3 &&
                pieces_to_check.contains(&(row - 1, col + 1)) &&
                pieces_to_check.contains(&(row - 2, col + 2)) &&
                pieces_to_check.contains(&(row - 3, col + 3)) {
                return true;
            }
        }

        false
    }
}

