fn resolve_dependencies(modules: Vec<&str>) -> Vec<&str> {
    let mut graph = std::collections::HashMap::new();
    let mut visited = std::collections::HashSet::new();
    let mut result = Vec::new();

    for module in &modules {
        graph.insert(module.to_string(), Vec::new());
    }

    for module in &modules {
        let dependencies = get_dependencies(module);
        graph.insert(module.to_string(), dependencies);
    }

    for module in &modules {
        if !visited.contains(module) {
            dfs(module, &graph, &mut visited, &mut result);
        }
    }

    result
}

fn get_dependencies(module: &str) -> Vec<String> {
    // Implement logic to read the module file and extract dependencies
    // For simplicity, assume a predefined mapping of modules to their dependencies
    match module {
        "cookie" => vec!["protocol".to_string()],
        "protocol" => vec!["router".to_string()],
        "router" => vec!["websocket".to_string()],
        "websocket" => Vec::new(),
        _ => Vec::new(),
    }
}

fn dfs(
    module: &str,
    graph: &std::collections::HashMap<String, Vec<String>>,
    visited: &mut std::collections::HashSet<String>,
    result: &mut Vec<String>,
) {
    visited.insert(module.to_string());
    for dependency in &graph[module] {
        if !visited.contains(dependency) {
            dfs(dependency, graph, visited, result);
        }
    }
    result.push(module.to_string());
}

