fn allocate_buffer_memory(device: &vk::Device, buffer: &mut Buffer, properties: vk::MemoryPropertyFlags) {
    let mem_requirements = unsafe { vk::GetBufferMemoryRequirements(*device, buffer.buffer) };

    let memory_type_index = find_memory_type(
        device,
        mem_requirements.memoryTypeBits,
        properties,
    );

    let alloc_info = vk::MemoryAllocateInfo {
        sType: vk::STRUCTURE_TYPE_MEMORY_ALLOCATE_INFO,
        pNext: std::ptr::null(),
        allocationSize: mem_requirements.size,
        memoryTypeIndex,
    };

    let buffer_memory = unsafe {
        let mut buffer_memory = std::ptr::null_mut();
        vk::AllocateMemory(*device, &alloc_info, std::ptr::null(), &mut buffer_memory)
            .expect("Failed to allocate buffer memory");
        buffer_memory
    };

    unsafe {
        vk::BindBufferMemory(*device, buffer.buffer, buffer_memory, 0)
            .expect("Failed to bind buffer memory");
    }

    buffer.buffer_memory = buffer_memory;
}

fn find_memory_type(
    device: &vk::Device,
    type_filter: u32,
    properties: vk::MemoryPropertyFlags,
) -> u32 {
    let mem_properties = unsafe { vk::GetPhysicalDeviceMemoryProperties(device.physical_device) };

    for i in 0..mem_properties.memoryTypeCount {
        if (type_filter & (1 << i)) != 0
            && mem_properties.memoryTypes[i as usize]
                .propertyFlags
                .contains(properties)
        {
            return i;
        }
    }

    panic!("Failed to find suitable memory type");
}

