macro_rules! lazy_static_include_array {
    (pub $name:ident: [$type:ty; $size:expr] => $file:expr) => {
        lazy_static! {
            pub static ref $name: [$type; $size] = {
                let file = File::open($file).expect("File not found");
                let reader = BufReader::new(file);
                let mut values = Vec::new();

                for line in reader.lines() {
                    let line = line.expect("Error reading line");
                    for value in line.split_whitespace() {
                        let parsed_value: $type = value.parse().expect("Error parsing value");
                        values.push(parsed_value);
                    }
                }

                if values.len() != $size {
                    panic!("Invalid number of elements in the file");
                }

                let mut array = [Default::default(); $size];
                for (i, &value) in values.iter().enumerate() {
                    array[i] = value;
                }

                array
            };
        }
    };
}

