macro_rules! delete {
    // Case for simple DELETE request without a request body
    ($url:tt, $client:expr, $base:expr) => {{
        let $url = &format!("{}/{}", $base, $url);
        $client.delete($url).send()?.error_for_status()?;
        Ok(())
    }};
    // Case for DELETE request with a request body
    ($t:ty, $url:tt, $body:expr, $client:expr, $base:expr) => {{
        let $url = &format!("{}/{}", $base, $url);
        let result: $t = {
            let res: Value = $client.delete($url)
                .json($body)  // Include the request body
                .send()?.error_for_status()?.json()?;
            res
        };
        Ok(result)
    }};
}

