fn validate_password(password: &str, pwd: &Password) -> (bool, Vec<char>) {
    let mut valid = true;
    let mut bad_chars = Vec::new();

    if password.len() < 8 {
        valid = false;
    }

    let uppercase_present = password.chars().any(|c| c.is_ascii_uppercase());
    if !uppercase_present {
