use std::collections::HashMap;

/// A constant value.
enum ConstValue {
    ConstVec(Vec<ConstValue>),
    ConstTuple(Vec<ConstValue>),
    ConstObject(HashMap<String, ConstValue>),
}

/// An interpreter value.
enum IrValue {
    /// A vector of values.
    Vec(Vec<IrValue>),
    /// An anonymous tuple.
    Tuple(Box<[IrValue]>),
    /// An anonymous object.
    Object(HashMap<String, IrValue>),
}

impl IrValue {
    /// Convert a constant value into an interpreter value.
    pub fn from_const(value: ConstValue) -> Self {
        match value {
            ConstValue::ConstVec(vec) => {
                let ir_vec: Vec<IrValue> = vec.into_iter().map(IrValue::from_const).collect();
                IrValue::Vec(ir_vec)
            }
            ConstValue::ConstTuple(tuple) => {
                let ir_tuple: Box<[IrValue]> = tuple.into_iter().map(IrValue::from_const).collect::<Vec<IrValue>>().into_boxed_slice();
                IrValue::Tuple(ir_tuple)
            }
            ConstValue::ConstObject(obj) => {
                let ir_obj: HashMap<String, IrValue> = obj.into_iter().map(|(k, v)| (k, IrValue::from_const(v))).collect();
                IrValue::Object(ir_obj)
            }
        }
    }
}

