use std::sync::{Arc, Mutex};
use std::time::{SystemTime, UNIX_EPOCH};

struct Logger {
    module_levels: Arc<Mutex<Vec<(String, log::LevelFilter)>>>,
}

impl Logger {
    fn new() -> Self {
        Logger {
            module_levels: Arc::new(Mutex::new(Vec::new())),
        }
    }

    fn set_module_level(&self, module: String, level: log::LevelFilter) {
        let mut levels = self.module_levels.lock().unwrap();
        levels.retain(|(m, _)| m != &module);
        levels.push((module, level));
    }

    fn format_log_message(message: &str) -> String {
        let timestamp = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .expect("Time went backwards")
            .as_nanos();
        format!("[{}] {}", timestamp, message)
    }

    fn log(&self, module: &str, level: log::Level, message: &str) {
        let levels = self.module_levels.lock().unwrap();
        if let Some((_, module_level)) = levels.iter().find(|(m, _)| module.starts_with(m)) {
            if level <= *module_level {
                println!("{}", Logger::format_log_message(message));
            }
        }
    }
}

