fn initialize_i2c(device: &mut I2CDevice) {
    // Enable the I2C peripheral clock
    I2C1::enable(&mut rcc.apb1);
    I2C1::reset(&mut rcc.apb1);

    let i2c = device.I2C1;

    // Disable the i2c peripheral while we set it up
    i2c.cr1.write(|w| w.pe().clear_bit());

    // Set clock frequency to standard mode (100 kHz)
    i2c.cr2.write(|w| unsafe { w.freq().bits(36) });

    // Set addressing mode to 7-bit addressing
    i2c.oar1.write(|w| w.oa1().bits(0));

    // Set duty cycle to 2
    i2c.ccr.write(|w| unsafe { w.ccr().bits(0x002D) });

    // Enable ACK
    i2c.cr1.modify(|_, w| w.ack().set_bit());

    // Set own address
    i2c.oar1.modify(|_, w| w.oa1en().set_bit());

    // Enable the i2c peripheral
    i2c.cr1.modify(|_, w| w.pe().set_bit());
}

