pub struct AccountState {
    account_id: u64,
    balance: f64,
}

impl AccountState {
    pub fn new(account_id: u64, initial_balance: f64) -> AccountState {
        AccountState {
            account_id,
            balance: initial_balance,
        }
    }

    pub fn get_balance(&self) -> f64 {
        self.balance
    }

    pub fn update_balance(&mut self, amount: f64) {
        self.balance += amount;
    }

    pub fn transfer(&mut self, recipient: &mut AccountState, amount: f64) -> Result<(), String> {
        if self.balance >= amount {
            self.balance -= amount;
            recipient.balance += amount;
            Ok(())
        } else {
            Err("Insufficient balance for transfer".to_string())
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_account_state() {
        let mut sender = AccountState::new(1, 100.0);
        let mut recipient = AccountState::new(2, 50.0);

        assert_eq!(sender.get_balance(), 100.0);
        assert_eq!(recipient.get_balance(), 50.0);

        sender.update_balance(-30.0);
        assert_eq!(sender.get_balance(), 70.0);

        let result = sender.transfer(&mut recipient, 40.0);
        assert_eq!(result, Ok(()));
        assert_eq!(sender.get_balance(), 30.0);
        assert_eq!(recipient.get_balance(), 90.0);

        let insufficient_result = sender.transfer(&mut recipient, 40.0);
        assert_eq!(insufficient_result, Err("Insufficient balance for transfer".to_string()));
        assert_eq!(sender.get_balance(), 30.0);
        assert_eq!(recipient.get_balance(), 90.0);
    }
}

