enum OperandSize {
    Dword,
    Qword,
}

fn vshufpd(operand1: [u64; 2], operand2: [u64; 2], control_byte: u8, operand_size: OperandSize) -> [u64; 2] {
    let mut result = [0u64; 2];
    match operand_size {
        OperandSize::Dword => {
            let mut temp_result = [0u64; 2];
            for i in 0..2 {
                let control = (control_byte >> (i * 2)) & 0b11;
                match control {
                    0b00 => temp_result[i] = operand1[0],
                    0b01 => temp_result[i] = operand1[1],
                    0b10 => temp_result[i] = operand2[0],
                    0b11 => temp_result[i] = operand2[1],
                    _ => unreachable!(),
                }
            }
            result = temp_result;
        }
        OperandSize::Qword => {
            for i in 0..2 {
                let control = (control_byte >> (i * 2)) & 0b11;
                match control {
                    0b00 => result[i] = operand1[0],
                    0b01 => result[i] = operand1[1],
                    0b10 => result[i] = operand2[0],
                    0b11 => result[i] = operand2[1],
                    _ => unreachable!(),
                }
            }
        }
    }
    result
}

