struct Inventory {
    items: Vec<(u32, String, u32, f64)>,
}

impl Inventory {
    // Add a new item to the inventory or update its quantity
    fn add_item(&mut self, id: u32, name: String, quantity: u32, price: f64) {
        let item_index = self.items.iter().position(|item| item.0 == id);
        if let Some(index) = item_index {
            let (_, _, existing_quantity, _) = &mut self.items[index];
            *existing_quantity += quantity;
        } else {
            self.items.push((id, name, quantity, price));
        }
    }

    // Remove a specified quantity of an item from the inventory
    fn remove_item(&mut self, id: u32, quantity: u32) {
        let item_index = self.items.iter().position(|item| item.0 == id);
        if let Some(index) = item_index {
            let (_, _, existing_quantity, _) = &mut self.items[index];
            if *existing_quantity <= quantity {
                self.items.remove(index);
            } else {
                *existing_quantity -= quantity;
            }
        }
    }

    // Display the current items in the inventory
    fn display_inventory(&self) {
        println!("Current Inventory:");
        for (id, name, quantity, price) in &self.items {
            println!("Item ID: {}, Name: {}, Quantity: {}, Price: ${}", id, name, quantity, price);
        }
        println!();
    }
}

