use std::cmp::min;

pub struct Pagination {
    page_size: u8,
    total_items: usize,
    current_page: u32,
}

impl Pagination {
    pub fn new(page_size: u8, total_items: usize) -> Self {
        Pagination {
            page_size,
            total_items,
            current_page: 1,
        }
    }

    pub fn total_pages(&self) -> u32 {
        ((self.total_items as f64) / (self.page_size as f64)).ceil() as u32
    }

    pub fn next_page(&mut self) -> Option<u32> {
        if self.current_page < self.total_pages() {
            self.current_page += 1;
            Some(self.current_page)
        } else {
            None
        }
    }

    pub fn prev_page(&mut self) -> Option<u32> {
        if self.current_page > 1 {
            self.current_page -= 1;
            Some(self.current_page)
        } else {
            None
        }
    }
}

trait Paginate<T> {
    fn paginate(&self, page: u32, page_size: u8) -> Vec<T>;
}

impl<T> Paginate<T> for Vec<T> {
    fn paginate(&self, page: u32, page_size: u8) -> Vec<T> {
        let start_index = ((page - 1) * page_size as u32) as usize;
        let end_index = min(start_index + page_size as usize, self.len());
        self[start_index..end_index].to_vec()
    }
}

fn main() {
    let items: Vec<i32> = (1..=100).collect();
    let pagination = Pagination::new(10, items.len());

    println!("Total pages: {}", pagination.total_pages());

    if let Some(next_page) = pagination.next_page() {
        println!("Next page: {}", next_page);
    }

    if let Some(prev_page) = pagination.prev_page() {
        println!("Previous page: {}", prev_page);
    }

    let current_page_items = items.paginate(pagination.current_page, pagination.page_size);
    println!("Current page items: {:?}", current_page_items);
}

