struct MovingAverage {
    window: Vec<f64>,
    size: usize,
    sum: f64,
}

impl MovingAverage {
    fn new(size: usize) -> Self {
        MovingAverage {
            window: Vec::new(),
            size,
            sum: 0.0,
        }
    }

    fn next(&mut self, val: f64) -> f64 {
        if self.window.len() < self.size {
            self.window.push(val);
            self.sum += val;
        } else {
            let first = self.window.remove(0);
            self.sum = self.sum - first + val;
            self.window.push(val);
        }
        self.sum / self.window.len() as f64
    }
}

