    let fit_u16z_result = FitFieldData::FitU16z(fit_u16z_data);

    // Return the appropriate result based on the data type
    match (fit_u8z_result, fit_u16z_result) {
        (FitFieldData::FitU8z(_), _) => Ok(fit_u8z_result),
        (_, FitFieldData::FitU16z(_)) => Ok(fit_u16z_result),
        _ => Err(FitError::InvalidDataType),
