fn configure_tls_client(cert: Vec<u8>, key: Vec<u8>) -> Result<ClientConfig, Box<dyn std::error::Error>> {
    let mut cfg = ClientConfig::new();

    // Load the certificate and private key
    let cert = Certificate(cert);
