where
    T: Expression,
    T::SqlType: IntoNullable,
{
    type SqlType = <T::SqlType as IntoNullable>::Nullable;
}

impl<T, DB> QueryFragment<DB> for MaybeNull<T>
where
    T: QueryFragment<DB>,
    DB: Backend,
{
    fn walk_ast(&self, mut out: DB::QueryBuilder) -> Result<(), DB::Error> {
        out.push_sql("COALESCE(");
        self.inner.walk_ast(out.reborrow())?;
        out.push_sql(", NULL)");
        Ok(())
    }
}

fn find_pattern(pattern: &Pattern, array: &[i32]) -> Option<usize> {
    let pattern_len = pattern.pattern.len();
    let array_len = pattern.array_len;

    if pattern_len > array_len {
        return None;  // Pattern length is greater than array length, pattern cannot be found
    }

    for i in 0..=(array_len - pattern_len) {
        if &array[i..(i + pattern_len)] == pattern.pattern.as_slice() {
            return Some(i);
        }
    }

    None  // Pattern not found in the array
}

