use std::collections::HashMap;

pub fn stats(vals: HashMap<String, String>, _opts: HashMap<String, String>) {
    // Convert string values to numeric values for calculations
    let numeric_vals: Vec<f64> = vals
        .values()
        .filter_map(|v| v.parse().ok())
        .collect();

    if numeric_vals.is_empty() {
        println!("No valid numeric data points provided.");
        return;
    }

    // Calculate mean (average)
    let mean: f64 = numeric_vals.iter().sum::<f64>() / numeric_vals.len() as f64;

    // Calculate median
    let mut sorted_vals = numeric_vals.clone();
    sorted_vals.sort_by(|a, b| a.partial_cmp(b).unwrap());
    let median: f64 = if sorted_vals.len() % 2 == 0 {
        let mid = sorted_vals.len() / 2;
        (sorted_vals[mid - 1] + sorted_vals[mid]) / 2.0
    } else {
        sorted_vals[sorted_vals.len() / 2]
    };

    // Calculate mode
    let mut freq_map: HashMap<&f64, usize> = HashMap::new();
    for val in &numeric_vals {
        *freq_map.entry(val).or_insert(0) += 1;
    }
    let mode = freq_map
        .iter()
        .max_by_key(|&(_, count)| count)
        .map(|(&val, _)| val)
        .unwrap();

    // Calculate range
    let range = sorted_vals.last().unwrap() - sorted_vals.first().unwrap();

    // Calculate standard deviation
    let variance: f64 = numeric_vals
        .iter()
        .map(|val| (val - mean).powi(2))
        .sum::<f64>() / numeric_vals.len() as f64;
    let std_deviation = variance.sqrt();

    // Output the calculated statistics
    println!("Mean: {:.2}", mean);
    println!("Median: {:.2}", median);
    println!("Mode: {:.2}", mode);
    println!("Range: {:.2}", range);
    println!("Standard Deviation: {:.2}", std_deviation);
}

