fn manage_action<T>(action_map: *mut ffi::GActionMap, actionptr: *mut ffi::GAction) {
    // Convert action_map and actionptr to Rust types
    let action_map_ref = unsafe { &mut *action_map };
    let actionptr_ref = unsafe { &mut *actionptr };

    // Extract necessary information from the pointers and perform the action addition
    let instance = &*(action_map as *mut T::Instance);
    let imp = instance.get_impl();
    let action: Borrowed<Action> = from_glib_borrow(actionptr_ref);

    // Add the action to the action map
