```

Write a function `sort_modules` that takes the list of module names as input and returns a sorted vector of module names in ascending order. The sorting should follow a specific order: 
1. Modules starting with the letter "b" should come first.
2. Modules starting with the letter "e" should come next.
3. Modules starting with the letter "h" should come last.
4. All other modules should be sorted in lexicographical order.

For example, given the input list:
```rust
["transform", "overlay", "empty", "filter", "progress_view", "rotation_3d_effect", "h_split", "background", "blur"]
```
The function should return:
```rust
["background", "blur", "empty", "filter", "h_split", "overlay", "progress_view", "rotation_3d_effect", "transform"]
```

code:
fn sort_modules(module_names: Vec<&str>) -> Vec<&str> {
    let mut b_modules = Vec::new();
    let mut e_modules = Vec::new();
    let mut h_modules = Vec::new();
    let mut other_modules = Vec::new();

    for module in module_names {
        match module.chars().next() {
            Some('b') => b_modules.push(module),
            Some('e') => e_modules.push(module),
            Some('h') => h_modules.push(module),
            _ => other_modules.push(module),
        }
    }

    b_modules.sort();
    e_modules.sort();
    h_modules.sort();
    other_modules.sort();

    let mut sorted_modules = Vec::new();
    sorted_modules.extend_from_slice(&b_modules);
    sorted_modules.extend_from_slice(&e_modules);
    sorted_modules.extend_from_slice(&other_modules);
    sorted_modules.extend_from_slice(&h_modules);

    sorted_modules
}

fn main() {
    let modules = vec![
        "transform", "overlay", "empty", "filter", "progress_view", "rotation_3d_effect", "h_split", "background", "blur"
    ];
    let sorted_modules = sort_modules(modules);
    println!("{:?}", sorted_modules);
}

