fn calculate_manhattan_distance(instructions: &str) -> i32 {
    let mut x = 0;
    let mut y = 0;

    for instruction in instructions.split(',') {
        let (dir, dist_str) = instruction.split_at(1);
        let dist: i32 = dist_str.parse().unwrap();

        match dir {
            "R" => x += dist,
            "L" => x -= dist,
            "U" => y += dist,
            "D" => y -= dist,
            _ => panic!("Invalid direction"),
        }
    }

    x.abs() + y.abs()
}

