fn submit_read_request(ring: &mut IoUring, fd: i32, buf: &mut [u8], offset: u64, size: u32) -> Result<usize, i32> {
    let mut sqe = ring.prepare_sqe().map_err(|e| e.raw_os_error().unwrap_or(1))?; // Get a mutable reference to a submission queue entry

    let mut iov = iovec_from_mut_slice(buf); // Create an iovec representing the buffer
    sqe.prep_read(fd, &mut iov, offset); // Prepare the read operation in the submission queue entry

    ring.submit_sqes().map_err(|e| e.raw_os_error().unwrap_or(1))?; // Submit the prepared read operation

    let cqe = ring.wait_for_cqe().map_err(|e| e.raw_os_error().unwrap_or(1))?; // Wait for the completion of the read operation
