The function shou

code:
fn process_effects(
    do_point: Vec<Point>,
    effect: Vec<EffectParams>,
    id: Identifier,
    limit: Vec<Limit>,
    limit_target: Vec<LimitTarget>,
    effect_target: Vec<EffectTarget>,
    effect_limit: Vec<EffectLimit>,
    values: Vec<Value>,
) -> Vec<(EffectId, Point)> {
    let mut eff_list = Vec::with_capacity(do_point.len());
    let mut last_eff = (0, 0);
    for (i, point) in do_point.iter().enumerate() {
        let (eff_id, eff_point) = effect::create(
            effect[i], id, point,
            limit[i], limit_target[i],
            effect_target[i], effect_limit[i], values[i], last_eff
        );
        last_eff = (eff_id, eff_point);
        eff_list.push(last_eff);
    }
    eff_list
}

use std::io;

fn is_prime(num: u64) -> bool {
    if num <= 1 {
        return false;
    }
    for i in 2..=(num as f64).sqrt() as u64 {
        if num % i == 0 {
            return false;
        }
    }
    true
}

fn fibonacci(n: u64) -> u64 {
    if n <= 1 {
        return n;
    }
    let mut fib = (0, 1);
    for _ in 2..=n {
        fib = (fib.1, fib.0 + fib.1);
    }
    fib.1
}

fn main() {
    println!("Enter the value of n:");
    let mut input = String::new();
    io::stdin().read_line(&mut input).expect("Failed to read line");
    let n: u64 = input.trim().parse().expect("Invalid input");

    let mut sum = 0;
    let mut count = 0;
    let mut i = 0;
    while count < n {
        let fib = fibonacci(i);
        if is_prime(fib) {
            sum += fib;
            count += 1;
        }
        i += 1;
    }

    println!("The sum of the first {} prime Fibonacci numbers is: {}", n, sum);
}

fn sum_array(arr: &[i32]) -> i32 {
    if arr.is_empty() {
        return 0;
    }

    arr[0] + sum_array(&arr[1..])
}

fn main() {
    let arr = [1, 2, 3, 4, 5];
    let sum = sum_array(&arr);
    println!("Sum: {}", sum);
}

