use std::io;

fn fibonacci_sum(n: u32) -> u32 {
    let mut sum = 0;
    let mut a = 0;
    let mut b = 1;

    for _ in 0..n {
        sum += a;
        let temp = a;
        a = b;
        b = temp + b;
    }

    sum
}

fn main() {
    println!("Enter the value of n: ");
    let mut input = String::new();
    io::stdin().read_line(&mut input).expect("Failed to read input");
    let n: u32 = input.trim().parse().expect("Invalid input");

    let sum = fibonacci_sum(n);

    println!("Sum of the first {} Fibonacci numbers is: {}", n, sum);
}

fn convert_to_title_case(input: &str) -> String {
    let mut output = String::new();
    let mut prev_char = ' ';
    let mut prev_is_letter = false;

    for c in input.chars() {
        if c.is_alphabetic() {
            if !prev_is_letter && prev_char != ' ' && prev_char != '-' && prev_char != '_' {
                output.push(' ');
            }
            if prev_is_letter && c.is_uppercase() {
                output.push(' ');
            }
            output.push(c);
            prev_is_letter = true;
        } else {
            output.push(c);
            prev_is_letter = false;
        }
        prev_char = c;
    }

    output.to_title_case()
}

fn main() {
    let input = "hello, world! this is a rust program to convert a string to title case. it should preserve the case of any acronyms or abbreviations within the string. additionally, it should handle multi-word acronyms or abbreviations by capitalizing the first letter of each word within the acronym or abbreviation.";
    let output = convert_to_title_case(input);

    println!("{}", output);
}

