}

fn is_prime(n: i32) -> bool {
    if n <= 1 {
        return false;
    }
    let limit = (n as f64).sqrt() as i32;
    for i in 2..=limit {
        if n % i == 0 {
            return false;
        }
    }
    true
}

fn get_primes(n: i32) -> Vec<i32> {
    let mut primes = vec![];
    for i in 2..=n {
        if is_prime(i) {
            primes.push(i);
        }
    }
    primes
}

